CREATE FUNCTION public.assign_deal_actor(_deal text,_user uuid,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin(auth.uid()) OR NOT public.can_access_deal(_deal) THEN RAISE EXCEPTION 'Administrator required'; END IF; IF _role::text NOT IN ('dcm','issuer_legal','counsel','syndicate_admin') THEN RAISE EXCEPTION 'Invalid deal team role'; END IF; IF NOT public.is_approved(_user) THEN RAISE EXCEPTION 'Approve this user before adding them'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(_user,_role) ON CONFLICT(user_id,role) DO NOTHING; INSERT INTO public.deal_team_members(deal_id,user_id,role) VALUES(_deal,_user,_role) ON CONFLICT DO NOTHING; INSERT INTO public.audit_log(id,action,entity_type,entity_id,user_id,details) VALUES(gen_random_uuid()::text,'DEAL_TEAM_ASSIGNED','deal',_deal,auth.uid()::text,jsonb_build_object('user',_user,'role',_role)::text); END $$;
REVOKE ALL ON FUNCTION public.assign_deal_actor(text,uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.assign_deal_actor(text,uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.move_deal_to_execution(_deal text,_actor uuid,_expected jsonb,_workspace jsonb,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.deals; st jsonb; BEGIN
 IF NOT public.is_admin(_actor) OR NOT public.is_approved(_actor) OR trim(coalesce(_note,''))='' THEN RAISE EXCEPTION 'Approved syndicate administrator and audit note required'; END IF;
 SELECT * INTO d FROM public.deals WHERE id=_deal FOR UPDATE;
 IF public.deal_phase(_deal)<>'setup' THEN RAISE EXCEPTION 'Deal is no longer in set-up'; END IF;
 IF d.bdt_state IS DISTINCT FROM _expected OR d.deal_workspace IS DISTINCT FROM _workspace THEN RAISE EXCEPTION 'Saved terms changed; review readiness again'; END IF;
 PERFORM 1 FROM public.deal_signoffs WHERE deal_id=_deal FOR UPDATE;
 IF (SELECT count(*) FROM public.deal_signoffs s JOIN public.deal_team_members t ON t.deal_id=s.deal_id AND t.user_id=s.user_id AND t.role=s.role JOIN public.user_roles r ON r.user_id=s.user_id AND r.role=s.role WHERE s.deal_id=_deal AND s.status='signed_off')<>12 THEN RAISE EXCEPTION 'Required actor sign-offs are incomplete'; END IF;
 st:=jsonb_set(d.bdt_state,'{stage}','2');
 UPDATE public.deals SET bdt_state=st,stage='Announced',stage_history=coalesce(d.stage_history,'[]')||jsonb_build_array(jsonb_build_object('from',d.stage,'to','Announced','timestamp',now(),'userId',_actor,'note',_note||' — Move to execution (IPTs)')),updated_at=now() WHERE id=_deal;
 INSERT INTO public.audit_log(id,action,entity_type,entity_id,user_id,details) VALUES(gen_random_uuid()::text,'DEAL_PHASE_CHANGED','deal',_deal,_actor::text,jsonb_build_object('from','setup','to','execution','stage','IPTs','note',_note)::text);
 END $$;
REVOKE ALL ON FUNCTION public.move_deal_to_execution(text,uuid,jsonb,jsonb,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.move_deal_to_execution(text,uuid,jsonb,jsonb,text) TO service_role;
CREATE FUNCTION public.deal_actor_context(_deal text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('phase',public.deal_phase(_deal),'roles',(SELECT coalesce(jsonb_agg(role::text),'[]') FROM public.user_roles WHERE user_id=auth.uid()),'openItems',(SELECT count(*) FROM (VALUES ('structure'),('size'),('tenor'),('bookrunners'),('issuer'),('law'),('restrictions'),('target'),('documents'),('listing'),('stabilisation'),('notices')) i(k) WHERE NOT EXISTS(SELECT 1 FROM public.deal_signoffs s WHERE s.deal_id=_deal AND s.item_key=i.k AND s.status='signed_off'))) WHERE public.copilot_member(_deal) $$;
REVOKE ALL ON FUNCTION public.deal_actor_context(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.deal_actor_context(text) TO authenticated,service_role;